Here is the commit message:
ipv4: Fix reference count leak when using error routes with
 nexthop objects

When a nexthop object is deleted, it is marked as dead and then
fib_table_flush() is called to flush all the routes that are using the
dead nexthop.

The current logic in fib_table_flush() is to only flush error routes
(e.g., blackhole) when it is called as part of network namespace
dismantle (i.e., with flush_all=true). Therefore, error routes are not
flushed when their nexthop object is deleted:

 # ip link add name dummy1 up type dummy
 # ip nexthop add id 1 dev dummy1
 # ip route add 198.51.100.1/32 nhid 1
 # ip route add blackhole 198.51.100.2/32 nhid 1
 # ip nexthop del id 1
 # ip route show
 blackhole 198.51.100.2 nhid 1 dev dummy1

As such, they keep holding a reference on the nexthop object which in
turn holds a reference on the nexthop device, resulting in a reference
count leak:

 # ip link del dev dummy1
 [   70.516258] unregister_netdevice: waiting for dummy1 to become free. Usage count = 2

Fix by flushing error routes when their nexthop is marked as dead.

IPv6 does not suffer from this problem.

Fixes: 493ced1ac47c ("ipv4: Allow routes to use nexthop objects")
Reported-by: Tetsuo Handa <penguin-kernel@I-love.SAKURA.ne.jp>
Closes: https://lore.kernel.org/netdev/d943f806-4da6-4970-ac28-b9373b0e63ac@I-love.SAKURA.ne.jp/
Reported-by: syzbot+881d65229ca4f9ae8c84@syzkaller.appspotmail.com
Signed-off-by: Ido Schimmel <idosch@nvidia.com>
Reviewed-by: David Ahern <dsahern@kernel.org>
Link: https://patch.msgid.link/20251221144829.197694-1-idosch@nvidia.com
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
fib_table_flush() in net/ipv4/fib_trie.c unconditionally skipped flushing error routes when flush_all is false, even if the nexthop object is dead. This caused error routes to retain references to the deleted nexthop and its device, leading to a reference count leak.

Here is the patch:
 /* Caller must hold RTNL. */
 int fib_table_flush(struct net *net, struct fib_table *tb, bool flush_all)
 {
 	struct trie *t = (struct trie *)tb->tb_data;
 	struct nl_info info = { .nl_net = net };
 	struct key_vector *pn = t->kv;
 	unsigned long cindex = 1;
 	struct hlist_node *tmp;
 	struct fib_alias *fa;
 	int found = 0;

 	/* walk trie in reverse order */
 	for (;;) {
 		unsigned char slen = 0;
 		struct key_vector *n;

 		if (!(cindex--)) {
 			t_key pkey = pn->key;

 			/* cannot resize the trie vector */
 			if (IS_TRIE(pn))
 				break;

 			/* update the suffix to address pulled leaves */
 			if (pn->slen > pn->pos)
 				update_suffix(pn);

 			/* resize completed node */
 			pn = resize(t, pn);
 			cindex = get_index(pkey, pn);

 			continue;
 		}

 		/* grab the next available node */
 		n = get_child(pn, cindex);
 		if (!n)
 			continue;

 		if (IS_TNODE(n)) {
 			/* record pn and cindex for leaf walking */
 			pn = n;
 			cindex = 1ul << n->bits;

 			continue;
 		}

 		hlist_for_each_entry_safe(fa, tmp, &n->leaf, fa_list) {
 			struct fib_info *fi = fa->fa_info;

 			if (!fi || tb->tb_id != fa->tb_id ||
 			    (!(fi->fib_flags & RTNH_F_DEAD) &&
 			     !fib_props[fa->fa_type].error)) {
 				slen = fa->fa_slen;
 				continue;
 			}

-			/* Do not flush error routes if network namespace is
-			 * not being dismantled
+			/* When not flushing the entire table, skip error
+			 * routes that are not marked for deletion.
 			 */
-			if (!flush_all && fib_props[fa->fa_type].error) {
+			if (!flush_all && fib_props[fa->fa_type].error &&
+			    !(fi->fib_flags & RTNH_F_DEAD)) {
 				slen = fa->fa_slen;
 				continue;
 			}

 			fib_notify_alias_delete(net, n->key, &n->leaf, fa,
 						NULL);
 			if (fi->pfsrc_removed)
 				rtmsg_fib(RTM_DELROUTE, htonl(n->key), fa,
 					  KEYLENGTH - fa->fa_slen, tb->tb_id, &info, 0);
 			hlist_del_rcu(&fa->fa_list);
 			fib_release_info(fa->fa_info);
 			alias_free_mem_rcu(fa);
 			found++;
 		}

 		/* update leaf slen */
 		n->slen = slen;

 		if (hlist_empty(&n->leaf)) {
 			put_child_root(pn, n->key, NULL);
 			node_free(n);
 		}
 	}

 	pr_debug("trie_flush found=%d\n", found);
 	return found;
 }



